import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 바로가기 대상 유형별 이동 경로 접두사
const LINK_PATHS: Record<string, string> = {
  DOCUMENT: '/documents',
  POST: '/posts',
  RESERVATION: '/reservations',
};
// 가정: 대상 식별자가 반드시 필요한 대상 유형 (schema.sql CHECK와 같다)
const TARGET_ID_REQUIRED = ['DOCUMENT', 'POST', 'RESERVATION'];
const NOTIFICATION_TYPES = ['ALERT', 'MENTION'];

function fail(message: string): never {
  throw new ApiError(400, 'VALIDATION_FAILED', message);
}

function textOf(value: unknown, label: string, max: number, required: boolean): string | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      fail(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  if (typeof value !== 'string') {
    fail(label + ' 형식이 올바르지 않습니다.');
  }
  const text = (value as string).trim();
  if (text === '') {
    if (required) {
      fail(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  if (text.length > max) {
    fail(label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return text;
}

function idOf(value: unknown, label: string, required: boolean): string | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      fail(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  const text = String(value).trim();
  if (typeof value === 'boolean' || !/^[0-9]{1,18}$/.test(text)) {
    fail(label + '은(는) 숫자여야 합니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr03604Controller {
  @Post('/notifications')
  @HttpCode(200)
  async createNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);

    const employeeId = idOf(data['employeeId'], '수신자', true);
    const notificationType = textOf(data['notificationType'], '알림 구분', 20, true);
    if (!NOTIFICATION_TYPES.includes(notificationType as string)) {
      fail('알림 구분은 ALERT 또는 MENTION이어야 합니다.');
    }
    const eventType = textOf(data['eventType'], '연계 이벤트 유형', 50, true);
    const title = textOf(data['title'], '제목', 300, true);
    const summary = textOf(data['summary'], '요약', 500, false);
    const targetType = textOf(data['targetType'], '바로가기 대상 유형', 50, false);
    const targetId = idOf(data['targetId'], '바로가기 대상 식별자', false);
    if (targetType !== null && TARGET_ID_REQUIRED.includes(targetType) && targetId === null) {
      fail('바로가기 대상 식별자를 입력해 주세요.');
    }

    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '수신 임직원이 조직도에 없습니다.');
      }

      const rows = await db.query(
        'INSERT INTO notification (employee_id, notification_type, event_type, title, summary, target_type, target_id, read_yn, occurred_at, created_at, updated_at) '
          + 'VALUES (CAST(:employeeId AS bigint), :notificationType, :eventType, :title, :summary, :targetType, CAST(:targetId AS bigint), false, now(), now(), now()) '
          + 'RETURNING notification_id AS "notificationId"',
        { employeeId, notificationType, eventType, title, summary, targetType, targetId },
      );

      // 가정: targetType과 targetId로 이동 경로를 구성한다
      let shortcutLink = '/notifications';
      if (targetType !== null && targetId !== null) {
        const base = LINK_PATHS[targetType] ?? '/' + encodeURIComponent(targetType.toLowerCase());
        shortcutLink = base + '/' + targetId;
      }

      return {
        notificationId: Number(rows[0]['notificationId']),
        shortcutLink,
      };
    });
  }
}

