import { useState } from 'react';
import {
  call,
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  RefName,
  Select,
  TextInput,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['ALERT', '알림'],
  ['MENTION', '@멘션'],
];

const EMPTY: Row = {
  employeeId: '',
  notificationType: 'ALERT',
  eventType: '',
  title: '',
  summary: '',
  targetType: '',
  targetId: '',
};

export default function FnSfr03604Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<Row>({ ...EMPTY });

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const submit = async () => {
    if (form.employeeId === '' || !form.notificationType || !form.eventType || !form.title) {
      throw new Error('수신자, 알림 구분, 연계 이벤트 유형, 제목을 입력해 주세요.');
    }
    const body: Row = {
      employeeId: form.employeeId,
      notificationType: form.notificationType,
      eventType: form.eventType,
      title: form.title,
    };
    if (form.summary) body.summary = form.summary;
    if (form.targetType) body.targetType = form.targetType;
    if (form.targetId !== '') body.targetId = form.targetId;
    const res = await call('POST', '/notifications', role, body);
    setResults([{ ...body, ...res }, ...results]);
    notify('알림을 저장했습니다.');
    setOpen(false);
    setForm({ ...EMPTY });
  };

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>저장한 알림</h2>
        <Tiles items={[['이번 화면 처리', results.length]]} />
      </section>
      <section className='box span-8'>
        <h2>메신저 알림 등록</h2>
        <Band total={results.length}>
          <button type='button' onClick={() => setOpen(true)}>알림 등록</button>
        </Band>
        <DataTable
          rows={results}
          empty='저장한 알림이 없습니다.'
          columns={[
            { key: 'notificationId', label: '알림 ID' },
            { key: 'employeeId', label: '수신자', render: (r) => <RefName table='employee' role={role} value={r.employeeId} /> },
            { key: 'notificationType', label: '알림 구분', render: (r) => <Badge value={r.notificationType} /> },
            { key: 'eventType', label: '연계 이벤트 유형' },
            { key: 'title', label: '제목' },
            { key: 'shortcutLink', label: '바로가기', render: (r) => <a href={String(r.shortcutLink)}>{String(r.shortcutLink)}</a> },
          ]}
        />
      </section>
      {open && (
        <Drawer title='알림 등록' onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit='저장'>
            <Field label='수신자' required>
              <LookupSelect table='employee' role={role} value={form.employeeId} onChange={(v) => set('employeeId', v)} />
            </Field>
            <Field label='알림 구분' required>
              <Select value={form.notificationType} onChange={(v) => set('notificationType', v)} options={TYPE_OPTIONS} />
            </Field>
            <Field label='연계 이벤트 유형' required>
              <TextInput value={form.eventType} onChange={(v) => set('eventType', v)} />
            </Field>
            <Field label='제목' required wide>
              <TextInput value={form.title} onChange={(v) => set('title', v)} />
            </Field>
            <Field label='요약' wide>
              <TextInput multiline value={form.summary} onChange={(v) => set('summary', v)} />
            </Field>
            <Field label='바로가기 대상 유형' hint='DOCUMENT, POST, RESERVATION 등'>
              <TextInput value={form.targetType} onChange={(v) => set('targetType', v)} />
            </Field>
            <Field label='바로가기 대상 식별자'>
              <NumberInput value={form.targetId} onChange={(v) => set('targetId', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
